// Private presentation helpers for the native EXIF inspector.
#include <richedit.h>
typedef struct { WORD tag; int group; double number[3]; wchar_t text[512]; } exif_summary_field_t;
static exif_summary_field_t summary_fields[64];
static int summary_field_count;
static DWORD summary_width,summary_height,summary_bits;
static double summary_dpi;
static ULONGLONG summary_bytes;
static HWND exif_summary,exif_tabs;
static HMODULE exif_richedit;
static int exif_details;
static const exif_summary_field_t *field(WORD tag,int group){int i;for(i=0;i<summary_field_count;i++)if(summary_fields[i].tag==tag && summary_fields[i].group==group)return &summary_fields[i];return NULL;}
static const wchar_t *field_text(WORD tag,int group){const exif_summary_field_t *p=field(tag,group);return p?p->text:L"";}
static double number_at(const BYTE *data,WORD type,DWORD i,int little){switch(type){case 1:case 7:return data[i];case 3:return rd16(data+i*2,little);case 4:case 13:return rd32(data+i*4,little);case 8:return (short)rd16(data+i*2,little);case 9:return (LONG)rd32(data+i*4,little);case 5:case 10:{DWORD a=rd32(data+i*8,little),b=rd32(data+i*8+4,little);double av=type==10?(double)(LONG)a:(double)a,bv=type==10?(double)(LONG)b:(double)b;return b?av/bv:0.0;}default:return 0.0;}}
static void remember_field(WORD tag,int group,WORD type,DWORD count,const BYTE *data,size_t bytes,int little){exif_summary_field_t *p;DWORD i;if(group==4 || group==3 || !count)return;
 if(group!=2){switch(tag){case 0x100:case 0x101:case 0x102:case 0x10f:case 0x110:case 0x112:case 0x11a:case 0x11b:case 0x128:case 0x132:case 0x829a:case 0x829d:case 0x8827:case 0x8833:case 0x9003:case 0x9004:case 0x9011:case 0x9204:case 0x9209:case 0x920a:case 0xa002:case 0xa003:case 0xa402:case 0xa403:case 0xa405:case 0xa434:break;default:return;}}
 else if(tag>7)return;
 if(summary_field_count>=64)return;p=&summary_fields[summary_field_count++];ZeroMemory(p,sizeof(*p));p->tag=tag;p->group=group;value_text(p->text,512,tag,type,count,data,bytes,little);for(i=0;i<count && i<3;i++)p->number[i]=number_at(data,type,i,little);
 if(group!=2){if(tag==0x100 || tag==0xa002)summary_width=(DWORD)p->number[0];else if(tag==0x101 || tag==0xa003)summary_height=(DWORD)p->number[0];else if(tag==0x102){summary_bits=0;for(i=0;i<count && i<8;i++)summary_bits+=(DWORD)number_at(data,type,i,little);}}
}
static void basic_image(const BYTE *data,size_t size){size_t pos;if(size>=2 && data[0]==0xff && data[1]==0xd8){pos=2;while(span(size,pos,2)){BYTE marker;size_t length;if(data[pos++]!=0xff)break;while(pos<size && data[pos]==0xff)pos++;if(pos>=size)break;marker=data[pos++];if(marker==0xda || marker==0xd9)break;if(marker==1 || (marker>=0xd0 && marker<=0xd7))continue;if(!span(size,pos,2))break;length=rd16(data+pos,0);if(length<2 || !span(size,pos,length))break;
 if(((marker>=0xc0 && marker<=0xc3) || (marker>=0xc5 && marker<=0xc7) || (marker>=0xc9 && marker<=0xcb) || (marker>=0xcd && marker<=0xcf)) && length>=8){summary_height=rd16(data+pos+3,0);summary_width=rd16(data+pos+5,0);summary_bits=data[pos+2]*data[pos+7];}
 if(marker==0xe0 && length>=16 && !memcmp(data+pos+2,"JFIF\0",5)){int unit=data[pos+9];DWORD density=rd16(data+pos+10,0);if(unit==1)summary_dpi=density;else if(unit==2)summary_dpi=density*2.54;}
 pos+=length;}}
 else if(size>=29 && !memcmp(data,"\211PNG\r\n\032\n",8)){BYTE bits=data[24],color=data[25];summary_width=rd32(data+16,0);summary_height=rd32(data+20,0);summary_bits=bits*(color==2?3:color==4?2:color==6?4:1);pos=8;while(span(size,pos,12)){DWORD length=rd32(data+pos,0);if(length>size-pos-12)break;if(!memcmp(data+pos+4,"pHYs",4) && length==9 && data[pos+16]==1)summary_dpi=rd32(data+pos+8,0)*.0254;pos+=(size_t)length+12;}}
 else if(size>=30 && !memcmp(data,"RIFF",4) && !memcmp(data+8,"WEBP",4)){pos=12;while(span(size,pos,8)){DWORD length=rd32(data+pos+4,1);const BYTE *p=data+pos+8;if(!span(size,pos+8,length))break;if(!memcmp(data+pos,"VP8X",4) && length>=10){summary_width=1+(DWORD)p[4]+((DWORD)p[5]<<8)+((DWORD)p[6]<<16);summary_height=1+(DWORD)p[7]+((DWORD)p[8]<<8)+((DWORD)p[9]<<16);summary_bits=p[0]&0x10?32:24;}else if(!summary_width && !memcmp(data+pos,"VP8 ",4) && length>=10){summary_width=rd16(p+6,1)&0x3fff;summary_height=rd16(p+8,1)&0x3fff;summary_bits=24;}else if(!summary_width && !memcmp(data+pos,"VP8L",4) && length>=5 && p[0]==0x2f){summary_width=1+p[1]+((p[2]&0x3f)<<8);summary_height=1+(p[2]>>6)+(p[3]<<2)+((p[4]&15)<<10);summary_bits=32;}if((length&1) && !span(size,pos+8+length,1))break;pos+=(size_t)length+8+(length&1);}}
 else if(size>=26 && data[0]=='B' && data[1]=='M'){summary_width=rd32(data+18,1);summary_height=rd32(data+22,1);if(size>=30)summary_bits=rd16(data+28,1);}
 else if(size>=10 && (!memcmp(data,"GIF87a",6) || !memcmp(data,"GIF89a",6))){summary_width=rd16(data+6,1);summary_height=rd16(data+8,1);}
}
static void section(wchar_t *text,const wchar_t *heading,const wchar_t *value){if(!*value)return;if(*text)append(text,8192,L"\r\n\r\n");append(text,8192,heading);append(text,8192,L"\r\n");append(text,8192,value);}
static void add_piece(wchar_t *line,size_t cap,const wchar_t *piece){if(!*piece)return;if(*line)append(line,cap,L" · ");append(line,cap,piece);}
static void bold_heading(HWND edit,const wchar_t *text,const wchar_t *heading){FINDTEXTEXW find;CHARFORMAT2W cf;(void)text;ZeroMemory(&find,sizeof(find));find.chrg.cpMin=0;find.chrg.cpMax=-1;find.lpstrText=(LPWSTR)heading;if(SendMessageW(edit,EM_FINDTEXTEXW,FR_DOWN,(LPARAM)&find)<0)return;ZeroMemory(&cf,sizeof(cf));cf.cbSize=sizeof(cf);cf.dwMask=CFM_BOLD|CFM_COLOR;cf.dwEffects=CFE_BOLD;cf.crTextColor=ui_text(exif_bg);SendMessageW(edit,EM_SETSEL,find.chrgText.cpMin,find.chrgText.cpMax);SendMessageW(edit,EM_SETCHARFORMAT,SCF_SELECTION,(LPARAM)&cf);}
static void build_summary(const wchar_t *path){wchar_t text[8192],value[2048],line[1024],piece[512];const exif_summary_field_t *p,*q;const wchar_t *date;unsigned int saved,unused;double dpi;int i;static const wchar_t *head_en[]={L"Date taken",L"Image",L"Camera settings",L"Lens",L"Location",L"File"};static const wchar_t *head_zh[]={L"拍摄日期",L"图像信息",L"相机设置",L"镜头",L"位置",L"文件信息"};
 _controlfp_s(&saved,0,0);_controlfp_s(&unused,_RC_NEAR,_MCW_RC);text[0]=0;
 date=field_text(0x9003,1);if(!*date)date=field_text(0x9004,1);if(!*date)date=field_text(0x132,0);
 wcsncpy_s(value,2048,*date?date:tr(L"Not recorded",L"未记录"),_TRUNCATE);if(wcslen(value)>=10 && value[4]==':' && value[7]==':'){value[4]='-';value[7]='-';}if(*field_text(0x9011,1)){append(value,2048,L" (UTC");append(value,2048,field_text(0x9011,1));append(value,2048,L")");}section(text,tr(head_en[0],head_zh[0]),value);
 value[0]=line[0]=0;if(summary_width && summary_height)fmt(value,2048,L"%lu × %lu",(unsigned long)summary_width,(unsigned long)summary_height);else append(value,2048,tr(L"Dimensions not recorded",L"尺寸未记录"));
 if(summary_bytes>=1024ULL*1024*1024)fmt(piece,512,L"%.2f GB",(double)summary_bytes/(1024.0*1024*1024));else if(summary_bytes>=1024ULL*1024)fmt(piece,512,L"%.2f MB",(double)summary_bytes/(1024.0*1024));else if(summary_bytes>=1024)fmt(piece,512,L"%.1f KB",(double)summary_bytes/1024.0);else fmt(piece,512,L"%I64u B",summary_bytes);add_piece(line,1024,piece);
 dpi=summary_dpi;p=field(0x11a,0);q=field(0x128,0);if(p && p->number[0]>0 && (!q || q->number[0]==2 || q->number[0]==3))dpi=p->number[0]*(q && q->number[0]==3?2.54:1.0);if(dpi>0){fmt(piece,512,L"%.0f dpi",dpi);add_piece(line,1024,piece);}if(summary_bits){fmt(piece,512,tr(L"%lu-bit",L"%lu 位"),(unsigned long)summary_bits);add_piece(line,1024,piece);}append(value,2048,L"\r\n");append(value,2048,line);section(text,tr(head_en[1],head_zh[1]),value);
 value[0]=0;p=field(0x10f,0);q=field(0x110,0);if(p && *p->text)append(value,2048,p->text);if(q && *q->text){if(*value)append(value,2048,L" ");append(value,2048,q->text);}line[0]=0;
 p=field(0x920a,1);if(p){fmt(piece,512,tr(L"%.6g mm",L"%.6g 毫米"),p->number[0]);add_piece(line,1024,piece);}p=field(0x829d,1);if(p){fmt(piece,512,L"f/%.6g",p->number[0]);add_piece(line,1024,piece);}p=field(0x829a,1);if(p && p->number[0]>0){if(p->number[0]<1)fmt(piece,512,tr(L"1/%.0f s",L"1/%.0f 秒"),1.0/p->number[0]);else fmt(piece,512,tr(L"%.6g s",L"%.6g 秒"),p->number[0]);add_piece(line,1024,piece);}if(*line){if(*value)append(value,2048,L"\r\n");append(value,2048,line);}line[0]=0;
 p=field(0x8827,1);if(!p)p=field(0x8833,1);if(p){fmt(piece,512,L"ISO %.0f",p->number[0]);add_piece(line,1024,piece);}p=field(0x9204,1);if(p){fmt(piece,512,tr(L"Exposure bias %+.6g EV",L"曝光补偿 %+.6g EV"),p->number[0]);add_piece(line,1024,piece);}p=field(0x9209,1);if(p)add_piece(line,1024,((DWORD)p->number[0]&1)?tr(L"Flash fired",L"已使用闪光灯"):tr(L"Flash did not fire",L"未使用闪光灯"));if(*line){if(*value)append(value,2048,L"\r\n");append(value,2048,line);}if(!*value)append(value,2048,tr(L"No camera information recorded",L"未记录相机信息"));section(text,tr(head_en[2],head_zh[2]),value);
 section(text,tr(head_en[3],head_zh[3]),field_text(0xa434,1));
 value[0]=0;p=field(2,2);q=field(4,2);if(p && q){double lat=p->number[0]+p->number[1]/60+p->number[2]/3600,lon=q->number[0]+q->number[1]/60+q->number[2]/3600;fmt(value,2048,L"%.6f° %s, %.6f° %s",lat,field_text(1,2),lon,field_text(3,2));p=field(6,2);q=field(5,2);if(p){fmt(piece,512,tr(L"\r\nAltitude %.6g m",L"\r\n海拔 %.6g 米"),p->number[0]*(q && q->number[0]==1?-1.0:1.0));append(value,2048,piece);}}else append(value,2048,tr(L"No location recorded",L"未记录位置"));section(text,tr(head_en[4],head_zh[4]),value);
 section(text,tr(head_en[5],head_zh[5]),path && *path?path:tr(L"No image selected",L"尚未选择图像"));
 SetWindowTextW(exif_summary,text);
 if(exif_richedit){CHARFORMAT2W cf;ZeroMemory(&cf,sizeof(cf));cf.cbSize=sizeof(cf);cf.dwMask=CFM_FACE|CFM_SIZE|CFM_COLOR|CFM_BOLD;cf.yHeight=200;cf.crTextColor=ui_text(exif_bg);wcscpy_s(cf.szFaceName,LF_FACESIZE,L"Source Han Sans CN");SendMessageW(exif_summary,EM_SETSEL,0,-1);SendMessageW(exif_summary,EM_SETCHARFORMAT,SCF_SELECTION,(LPARAM)&cf);for(i=0;i<6;i++)bold_heading(exif_summary,text,tr(head_en[i],head_zh[i]));SendMessageW(exif_summary,EM_SETSEL,0,0);SendMessageW(exif_summary,EM_SCROLL,SB_TOP,0);}
 _controlfp_s(&unused,saved,_MCW_RC);
}
static void show_exif_page(void){ShowWindow(exif_summary,exif_details?SW_HIDE:SW_SHOW);ShowWindow(exif_list,exif_details?SW_SHOW:SW_HIDE);}
